message.content:
{"diagnosis": "Loopback read via reg_dat_do returned 0xff (idle ~0) instead of 0xa5, showing recv_buf_valid never latched correct recv_buf_data. Reset leaves recv_state in 1, the half-bit wait gated by 2*recv_divcnt > cfg_divider, instead of idle state 0 that waits for !ser_rx. Without start-bit gating the receiver advances to state 2 after half a divider period and mis-samples the frame, so the byte is lost.", "patch_diff": "diff --git a/picosoc/simpleuart.v b/picosoc/simpleuart.v
--- a/picosoc/simpleuart.v
+++ b/picosoc/simpleuart.v
@@ -66,7 +66,7 @@
 	always @(posedge clk) begin
 		if (!resetn) begin
-			recv_state <= 1;
+			recv_state <= 0;
 			recv_divcnt <= 0;
 			recv_pattern <= 0;
 			recv_buf_data <= 0;
 			recv_buf_valid <= 0;
", "expected": "tohost PASS (not FAIL 0xdead), no uart data mismatch trap, loopback got 0xa5 want 0xa5"}

